(function(){
class TurnBook {
  constructor(el, opts = {}) {
    this.el = el;
    this.opts = opts;
    this.handlers = {};
    this.pages = Array.from(el.children);
    this.total = this.pages.length;
    this.page = 1;
    this.isAnimating = false;
    this.setup();
    this.layout();
    window.addEventListener('resize', () => this.layout());
  }

  setup() {
    this.el.style.perspective = '2400px';
    this.el.style.transformStyle = 'preserve-3d';
    this.pages.forEach((p) => {
      p.style.position = 'absolute';
      p.style.top = '0';
      p.style.height = '100%';
      p.style.backfaceVisibility = 'hidden';
      p.style.transformStyle = 'preserve-3d';
      p.style.transition = 'transform 520ms cubic-bezier(.2,.7,.2,1), filter 520ms ease';
      p.style.willChange = 'transform, filter';
      p.style.display = 'none';
    });
  }

  on(name, fn) { (this.handlers[name] || (this.handlers[name] = [])).push(fn); }
  emit(name, ...args) {
    (this.handlers[name] || []).forEach((fn) => fn.call(this.el, { type: name }, ...args));
    if (this.opts.when && typeof this.opts.when[name] === 'function') this.opts.when[name].call(this.el, { type: name }, ...args);
    this.el.dispatchEvent(new CustomEvent(name, { detail: args }));
  }

  _applyPage(pageEl, side) {
    pageEl.style.display = 'block';
    pageEl.style.width = '50%';
    pageEl.style.left = side === 'left' ? '0' : '50%';
    pageEl.style.right = 'auto';
    pageEl.style.transformOrigin = side === 'left' ? 'right center' : 'left center';
    pageEl.style.filter = 'brightness(1)';
    pageEl.classList.toggle('left', side === 'left');
    pageEl.classList.toggle('right', side === 'right');
  }

  layout() {
    this.pages.forEach((p) => { p.style.display = 'none'; p.style.transform = 'rotateY(0deg)'; p.style.marginLeft='0'; p.style.filter='brightness(1)'; });
    if (this.page === 1) {
      const cover = this.pages[0];
      cover.style.display = 'block';
      cover.style.width = '50%';
      cover.style.left = '50%';
      cover.style.marginLeft = '-25%';
      cover.classList.remove('left'); cover.classList.add('right'); cover.style.zIndex = 50;
      return;
    }
    if (this.page >= this.total) {
      const back = this.pages[this.total - 1];
      back.style.display = 'block';
      back.style.width = '50%';
      back.style.left = '0';
      back.style.marginLeft = '25%';
      back.classList.remove('right'); back.classList.add('left'); back.style.zIndex = 50;
      return;
    }
    const leftNum = this.page % 2 === 0 ? this.page : this.page - 1;
    const rightNum = leftNum + 1;
    const left = this.pages[leftNum - 1];
    const right = this.pages[rightNum - 1];
    this._applyPage(left, 'left');
    this._applyPage(right, 'right');
    left.style.zIndex = 40; right.style.zIndex = 41;
  }

  _animateTurn(direction, from, to) {
    const duration = 520;
    const done = () => { this.page = to; this.layout(); this.isAnimating = false; };

    if (direction === 'next') {
      const flipPageNum = from === 1 ? 1 : (from % 2 === 0 ? from + 1 : from);
      const flip = this.pages[flipPageNum - 1];
      if (!flip) return done();
      this.layout();
      flip.style.display = 'block';
      flip.style.width = '50%';
      flip.style.left = '50%';
      flip.style.transformOrigin = 'left center';
      flip.style.zIndex = 99;
      flip.style.filter = 'brightness(0.92)';
      requestAnimationFrame(() => {
        flip.style.transform = 'rotateY(-168deg)';
        setTimeout(done, duration);
      });
    } else {
      const flipPageNum = from >= this.total ? this.total : (from % 2 === 0 ? from : from - 1);
      const flip = this.pages[flipPageNum - 1];
      if (!flip) return done();
      this.layout();
      flip.style.display = 'block';
      flip.style.width = '50%';
      flip.style.left = '0';
      flip.style.transformOrigin = 'right center';
      flip.style.transform = 'rotateY(-168deg)';
      flip.style.zIndex = 99;
      flip.style.filter = 'brightness(0.92)';
      requestAnimationFrame(() => {
        flip.style.transform = 'rotateY(0deg)';
        setTimeout(done, duration);
      });
    }
  }

  turn(direction) {
    if (this.isAnimating) return;
    let next = this.page;
    if (direction === 'next') {
      if (this.page === 1) next = 2;
      else if (this.page < this.total - 1) next = this.page + 2;
      else next = this.total;
    } else if (direction === 'previous') {
      if (this.page === this.total) next = this.total - 2;
      else if (this.page > 2) next = this.page - 2;
      else next = 1;
    }
    if (next === this.page) return;
    this.emit('turning', next, []);
    this.isAnimating = true;
    this._animateTurn(direction, this.page, Math.max(1, Math.min(this.total, next)));
  }
}
window.TurnBook = TurnBook;
})();
